(function(){
 if(!document.body.classList.contains('shared-app'))return;
 let planningGeneration=0;const priorProgram=renderProgram;
 renderProgram=async function(){const request=++planningGeneration;priorProgram();const pid=project?.id;if(!pid)return;try{const list=await checked(db.from('sm_milestones').select('*').eq('project_id',pid).order('due'));if(request!==planningGeneration||project?.id!==pid||scope!=='program')return;const root=el('#sharedContent');root.insertAdjacentHTML('beforeend',`<section class="panel" style="margin-top:22px"><div class="panel-header"><h2>موعدهای تحویل پروژه</h2>${management()?'<button class="secondary" id="newMilestone">＋ ثبت تحویل</button>':''}</div>${list.map(m=>`<div class="shared-member"><div><b>${esc(m.title)}</b><small>${date(m.starts_on)} تا ${date(m.due)} · ${esc(person(m.owner_id))} · ${{planned:'برنامه‌ریزی‌شده',active:'در حال اجرا',delivered:'تحویل‌شده'}[m.status]}</small></div>${management()?`<button class="text-btn" data-edit-milestone="${m.id}">ویرایش</button>`:''}</div>`).join('')||'<div class="shared-empty">هنوز تحویلی ثبت نشده است.</div>'}</section>`);if(el('#newMilestone'))el('#newMilestone').onclick=()=>milestoneForm();root.querySelectorAll('[data-edit-milestone]').forEach(b=>b.onclick=()=>milestoneForm(list.find(x=>x.id===b.dataset.editMilestone)));for(const m of list){const cell=root.querySelector(`[data-calendar-date="${m.due}"]`);if(cell){const b=document.createElement('button');b.className='cal-event delivery';b.textContent='◆ '+m.title;b.onclick=()=>management()?milestoneForm(m):message(m.title+' · '+date(m.due));cell.append(b)}}}catch(e){message(failure(e))}};
 function milestoneForm(m=null){selectedTask=null;modal(`${modalHead(m?'ویرایش تحویل':'ثبت تحویل پروژه')}<form id="milestoneForm"><label>عنوان<input name="title" required maxlength="200" value="${esc(m?.title||'')}"></label><label>شرح<textarea name="description" maxlength="10000">${esc(m?.description||'')}</textarea></label><label>مسئول<select name="owner">${members.filter(x=>x.active).map(x=>`<option value="${x.id}" ${x.id===m?.owner_id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>شروع<input name="start" type="date" required value="${m?.starts_on||''}"></label><label>موعد تحویل<input name="due" type="date" required value="${m?.due||''}"></label><label>وضعیت<select name="status">${[['planned','برنامه‌ریزی‌شده'],['active','در حال اجرا'],['delivered','تحویل‌شده']].map(([v,l])=>`<option value="${v}" ${m?.status===v?'selected':''}>${l}</option>`).join('')}</select></label><button class="primary">ذخیره تحویل</button></form>`);el('#milestoneForm').onsubmit=async e=>{e.preventDefault();if(busy)return;const f=new FormData(e.target);if(f.get('start')>f.get('due'))return message('موعد تحویل باید بعد از شروع باشد.');busy=true;try{await rpc('sm_save_milestone',{p_project:project.id,p_id:m?.id||null,p_revision:m?.revision||0,p_title:f.get('title'),p_description:f.get('description'),p_owner:f.get('owner'),p_start:f.get('start'),p_due:f.get('due'),p_status:f.get('status')});el('#sharedDialog').close();await renderProgram(true);message('تحویل و سابقهٔ تغییر در دیتابیس ذخیره شد.')}catch(err){message(failure(err))}finally{busy=false}}}
 window.SamandisMilestoneForm=milestoneForm;

})();
